	req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
	if err != nil {
		return nil, err
	}
	if info.Username != "" && info.Password != "" {
		req.SetBasicAuth(info.Username, info.Password)
	}
	resp, err := nexusHTTPClient.Do(req)
	if err != nil {
		// A refused redirect comes back without the URL it pointed to, which
		// may be signed.
		return nil, oci.StripRedirectTarget(err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		status := &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
		if resp.StatusCode != http.StatusNotFound {
			return nil, status
		}
		errBody, err := oci.ReadAllLimited(resp.Body, maxNexusErrorBody)
		if err != nil {
			if ctxErr := ctx.Err(); ctxErr != nil {
				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
			}
			return nil, status
		}
		if isRepositoryNotFound(errBody) {
			return nil, &repositoryNotFoundError{status: status}
		}
		return nil, status
	}
	body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
	if err != nil {
		// Which error net/http gives a body cut by a cancel varies: report the
		// context's own.
		if ctxErr := ctx.Err(); ctxErr != nil {
			return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
		}
		return nil, fmt.Errorf("read Nexus response: %w", err)
	}
	return body, nil
}"},{"rank":4,"score":42.9922,"file_path":"internal/ui/oci_resources/browser_summary.go","start_line":115,"end_line":119,"focus_line":117,"snippet_start_line":116,"snippet_end_line":117,"symbol_start_line":104,"symbol_end_line":152,"language":"Go","kind":"function","symbol_id":"local/devdesk-629-nexus-measure-fixes:Go:internal/ui/oci_resources/browser_summary.go:function:summarizeSearch","symbol_name":"summarizeSearch","qualified_name":"summarizeSearch","signature":"func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool, label func(key string) string, role func(key string) nexusRole) searchSummary","signals":["body","signature","symbol-usage"],"snippet":"		}
